<script lang="ts">import type { Snippet } from 'svelte'; import type { HTMLAnchorAttributes } from 'svelte/elements'; import { getNavigationMenuContext } from './navigation-menu-context.svelte.js'; export interface Props extends Omit<HTMLAnchorAttributes, 'children'> { children?: Snippet; href: string; active?: boolean; ref?: HTMLAnchorElement | null; } let { children, href, active = false, ref = $bindable(null), onclick, ...rest }: Props = $props(); const navigation = getNavigationMenuContext();</script><a bind:this={ref} {...rest} {href} aria-current={active ? 'page' : undefined} data-active={active ? '' : undefined} onclick={(event) => { onclick?.(event as MouseEvent & { currentTarget: EventTarget & HTMLAnchorElement }); if (!event.defaultPrevented) navigation.setValue(null, event); }}>{@render children?.()}</a>
